import{_ as e,o,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-07-16","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-07-16","date":"2025-07-16T00:00:00.000Z","updated":"2025-07-18T00:00:00.000Z","tags":["Ceph","RGW","Sharding","Compatibility","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-16.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-16.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-16.md"};function s(a,t,g,p,l,_){return o(),i("div",null,[...t[0]||(t[0]=[n("<p>在2025年7月16日的Ceph RGW重构会议上，社区成员讨论了持久化Topic队列的分片方案，旨在提升Ceph分布式存储性能。</p><p><strong>会议主要议题</strong>：</p><ol><li><strong>分片方案</strong>：为了提高性能，会议引入了分片（Sharding）方案，将一个Topic分为多个Shards，以支持并行处理。</li><li><strong>兼容性问题</strong>：新方案需要考虑与旧版RGW的兼容性，包括向后兼容和向前兼容问题。</li><li><strong>技术细节</strong>：会议讨论了RADOS对象命名、旧版RGW的行为以及Notify Manager的优化。</li><li><strong>性能权衡</strong>：分片主要针对写入并行化，而非队列容量问题，因此不需要Resharding支持。</li></ol><p><strong>决定的事项</strong>：</p><ol><li><strong>分片默认值</strong>：初步决定默认分片数为11，但初始部署时设为1以确保兼容性。</li><li><strong>文档补充</strong>：要求补充文档，明确用户在集群全量升级后调整分片数。</li><li><strong>清理逻辑</strong>：由于处理成本过高，暂不添加复杂清理代码。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li><strong>PR审核</strong>：Adash的分片实现PR需要进一步审查。</li><li><strong>测试验证</strong>：确认混合集群场景下残留Shard的实际影响，并检查多Shard写入的并行性能提升效果。</li><li><strong>Tentacle版本发布</strong>：解决Maven/Kafka依赖问题，并验证Lifetime Fix。</li></ol><p>会议还讨论了Tentacle版本发布问题，包括Maven/Kafka依赖和Lifetime Fix的验证。</p><p>本次会议对于Ceph RGW的性能优化和兼容性提升具有重要意义。通过分片方案，Ceph分布式存储的性能将得到显著提升，同时也确保了与旧版系统的兼容性。后续的测试和验证工作将确保新功能的稳定性和可靠性。</p>",9)])])}const R=e(r,[["render",s]]);export{c as __pageData,R as default};
